<!doctype html><html><head><meta charset="utf-8"><title>Voucher {{ $document->id }}</title><style>body{font:16px Arial;margin:40px;color:#172033}dl{display:grid;grid-template-columns:180px 1fr;gap:16px}dt{font-weight:bold}dd{margin:0}button{padding:12px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save PDF</button><h1>{{ $sahodaya->name }}</h1><h2>{{ ucfirst($document->kind) }} voucher · {{ $document->id }}</h2><dl><dt>Status</dt><dd>{{ $document->status }}</dd><dt>Date</dt><dd>{{ $document->document_date->format('d M Y') }}</dd><dt>Payee / vendor</dt><dd>{{ $document->vendor?->name ?? '—' }}</dd><dt>Account</dt><dd>{{ $document->accountHead?->name ?? 'Transfer / advance' }}</dd><dt>Payment account</dt><dd>{{ $document->bankAccount?->account_name ?? 'Cash & Bank' }}</dd><dt>Amount</dt><dd>INR {{ number_format($document->amount,2) }}</dd><dt>Reference</dt><dd>{{ $document->reference }}</dd><dt>Description</dt><dd>{{ $document->description }}</dd><dt>Journal</dt><dd>{{ $document->journal_id ?? 'Not posted' }}</dd></dl></body></html>
